import static com.rpb.reservation.workforce.payroll.segment.SegmentDtos.*;
import static com.rpb.reservation.workforce.payroll.segment.SegmentMoney.*;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.util.*;import java.math.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class SegmentService {
 private final WorkforceAccess gate;private final PayrollAccess access;private final SegmentRepository repo;private final PayrollRepository payroll;private final PayrollSources sources;private final WorkforceEmployeeRepository employees;private final WorkforceAudit audit;private final Clock clock;private final SegmentCalculation calculation;private final JdbcTemplate jdbc;private final WorkforceJson json;
 public SegmentService(WorkforceAccess gate,PayrollAccess access,SegmentRepository repo,PayrollRepository payroll,PayrollSources sources,PayrollCalculationService calculator,WorkforceEmployeeRepository employees,WorkforceAudit audit,WorkforceJson json,JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.json=json;this.gate=gate;this.access=access;this.repo=repo;this.payroll=payroll;this.sources=sources;this.employees=employees;this.audit=audit;this.clock=clock;this.calculation=new SegmentCalculation(repo,sources,calculator,jdbc,json);}
 private YearMonth month(String s){try{if(s==null||!s.matches("[0-9]{4}-[0-9]{2}"))throw WorkforceException.invalid();var m=YearMonth.parse(s);if(m.getYear()<2000||m.getYear()>2100)throw WorkforceException.invalid();return m;}catch(DateTimeException e){throw WorkforceException.invalid();}}
 private LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));}
 private SegmentRepository.State state(CurrentActor a,UUID store,UUID id){gate.enter(a,store);var s=repo.find(a.tenantId(),id).orElseThrow(WorkforceException::missing);access.enter(a,store,s.company(),s.calculation()==null?List.of():s.calculation().cumulative().lines().stream().flatMap(l->l.sources().stream()).map(SourceRef::storeId).toList());access.employee(a,s.company(),s.employee());return s;}
 private void noSelf(CurrentActor a,SegmentRepository.State s){if(a.actorId().equals(employees.find(a.tenantId(),s.employee()).orElseThrow(WorkforceException::missing).accountId()))throw WorkforceException.forbidden();}
 private void lock(CurrentActor a,SegmentRepository.State s){payroll.lockSources(a.tenantId());repo.lock(a.tenantId(),s.company(),s.employee(),s.month());}
 private void normalConflict(SegmentRepository.State s){var normal=payroll.forMonth(s.tenant(),s.company(),s.month()).orElse(null);if(normal!=null&&SegmentRepository.formal(normal.status())&&normal.calculation()!=null&&normal.calculation().lines().stream().anyMatch(l->l.employeeId().equals(s.employee())))throw new WorkforceException("SEGMENT_ORDINARY_ALREADY_CONFIRMED",409);}
 public Detail detail(CurrentActor a,UUID store,UUID id){return view(a,store,state(a,store,id));}
 @Transactional public Detail save(CurrentActor a,UUID store,UUID id,Write w){
  if(id==null||w==null||w.companyId()==null||w.employeeId()==null||w.expectedVersion()==null||w.expectedVersion()<0||w.cutoff()==null||w.note()==null||w.note().isBlank()||w.note().length()>500)throw WorkforceException.invalid();var m=month(w.month());
  if(!YearMonth.from(w.cutoff()).equals(m)||!w.cutoff().isBefore(today()))throw new WorkforceException("SEGMENT_CUTOFF_NOT_COMPLETE",409);
  for(var value:Arrays.asList(w.workingDays(),w.payableDays()))if(value!=null&&!value.matches("[0-9]{1,2}(\\.[0-9]{1,2})?"))throw WorkforceException.invalid();
  if(w.workingDays()!=null&&(n(w.workingDays()).signum()<=0||n(w.workingDays()).compareTo(BigDecimal.valueOf(31))>0||n(w.workingDays()).stripTrailingZeros().scale()>0)||w.payableDays()!=null&&(n(w.payableDays()).signum()<0||n(w.payableDays()).compareTo(BigDecimal.valueOf(31))>0||n(w.payableDays()).multiply(BigDecimal.valueOf(2)).stripTrailingZeros().scale()>0)||w.workingDays()!=null&&w.payableDays()!=null&&n(w.payableDays()).compareTo(n(w.workingDays()))>0)throw WorkforceException.invalid();
  access.enter(a,store,w.companyId());access.employee(a,w.companyId(),w.employeeId());payroll.lockSources(a.tenantId());gate.sourceWrite(a);repo.lock(a.tenantId(),w.companyId(),w.employeeId(),m);
  var old=repo.find(a.tenantId(),id).orElse(null);if(old!=null){state(a,store,id);if(old.request().equals(w)&&old.version()==w.expectedVersion()+1)return view(a,store,old);if(old.version()!=w.expectedVersion()||!Set.of("draft","calculated").contains(old.status())||!old.company().equals(w.companyId())||!old.employee().equals(w.employeeId())||!old.cutoff().equals(w.cutoff()))throw WorkforceException.conflict();repo.update(a,old,"draft",w,null);audit.changed(a,store,"segment.inputs",id,old.request(),w);return view(a,store,repo.find(a.tenantId(),id).orElseThrow());}
  if(w.expectedVersion()!=0)throw WorkforceException.conflict();var previous=repo.latest(a.tenantId(),w.companyId(),w.employeeId(),m).orElse(null);var from=previous==null?m.atDay(1):previous.cutoff().plusDays(1);if(w.cutoff().isBefore(from))throw new WorkforceException("SEGMENT_RANGE_OVERLAP",409);
  var candidate=new SegmentRepository.State(id,a.tenantId(),w.companyId(),w.employeeId(),m,from,w.cutoff(),"draft",1,w,null);normalConflict(candidate);var capture=calculation.capture(candidate);access.enter(a,store,w.companyId(),capture.stores());if(capture.lines().isEmpty()||payroll.employmentPeriods(a.tenantId(),w.companyId(),w.employeeId(),m).stream().noneMatch(period->!period.from().isAfter(w.cutoff())&&!period.to().isBefore(m.atDay(1))))throw new WorkforceException("SEGMENT_EMPLOYMENT_MISSING",409);
  repo.create(a,id,w,from);audit.changed(a,store,"segment.create",id,null,Map.of("employeeId",w.employeeId(),"from",from,"cutoff",w.cutoff()));return view(a,store,repo.find(a.tenantId(),id).orElseThrow());
 }
 @Transactional public Detail action(CurrentActor a,UUID store,UUID id,UUID command,Action w){
  if(command==null||w==null||w.expectedVersion()==null||w.expectedVersion()<1||w.note()==null||w.note().isBlank()||w.note().length()>500||!Set.of("calculate","confirm","publish","void").contains(Objects.toString(w.action(),"")))throw WorkforceException.invalid();
  var initial=state(a,store,id);lock(a,initial);gate.sourceWrite(a);repo.commandLock(a.tenantId(),command);var s=state(a,store,id);var replay=repo.replay(a,store,id,command,w);if(replay.isPresent())return replay.get();if(s.version()!=w.expectedVersion())throw WorkforceException.conflict();Calculation c=s.calculation();String status;
  switch(w.action()){
   case "calculate","confirm" -> {if(!Set.of("draft","calculated").contains(s.status()))throw WorkforceException.conflict();normalConflict(s);if(!s.cutoff().isBefore(today()))throw new WorkforceException("SEGMENT_CUTOFF_NOT_COMPLETE",409);var capture=calculation.capture(s);access.enter(a,store,s.company(),capture.stores());var fresh=calculation.calculate(s);if(w.action().equals("confirm")){noSelf(a,s);if(!s.status().equals("calculated")||c==null||!c.fingerprint().equals(fresh.fingerprint()))throw new WorkforceException("WORKFORCE_PAYROLL_SOURCE_CHANGED",409);if(!fresh.issues().isEmpty())throw new WorkforceException("WORKFORCE_PAYROLL_BLOCKED",409);repo.claim(s);status="confirmed";}else{c=fresh;status="calculated";}}
   case "publish" -> {if(!s.status().equals("confirmed"))throw WorkforceException.conflict();noSelf(a,s);status="published";}
   case "void" -> {if(!Set.of("draft","calculated").contains(s.status()))throw WorkforceException.conflict();status="voided";}
   default -> throw WorkforceException.invalid();
  }
  repo.update(a,s,status,s.request(),c);audit.changed(a,store,"segment."+w.action(),id,Map.of("status",s.status(),"version",s.version()),Map.of("status",status,"note",w.note()));var response=view(a,store,repo.find(a.tenantId(),id).orElseThrow());repo.command(a,store,id,command,w,response);return response;
 }
 public Page page(CurrentActor a,UUID store,UUID company,String value){access.enter(a,store,company);var m=month(value);var records=repo.month(a.tenantId(),company,m).stream().map(s->view(a,store,state(a,store,s.id()))).toList();var normal=payroll.forMonth(a.tenantId(),company,m).orElse(null);var totals=new ArrayList<PayBreakdown.Values>();var people=new HashSet<UUID>();int count=0;
  if(normal!=null&&SegmentRepository.formal(normal.status())&&normal.calculation()!=null){access.enter(a,store,company,normal.calculation().lines().stream().flatMap(l->l.sources().stream()).map(SourceRef::storeId).toList());totals.add(PayBreakdown.of(normal.calculation()));normal.calculation().lines().forEach(l->people.add(l.employeeId()));count++;}
  for(var s:repo.formal(a.tenantId(),company,m)){people.add(s.employee());totals.add(s.calculation().delta());count++;}
  // Monthly formal totals include supplements exactly once; payment rows are not wages.
  for(var b:new com.rpb.reservation.workforce.payroll.supplemental.SupplementalRepository(jdbc,json).forMonth(a.tenantId(),company,m)){people.add(b.employeeId());var v=b.calculation();String originEr=v.balances().stream().filter(balance->balance.month().equals(m.toString())).findFirst().map(balance->balance.employerCpf().liabilityDelta()).orElse(null);totals.add(new PayBreakdown.Values("0.00","0.00",v.grossDelta(),"0.00","0.00","0.00","0.00",v.cdacDeduction(),v.employeeCpfDeduction(),originEr,v.sdlDelta(),"0.00",v.grossDelta(),v.employeeCashPayable(),originEr==null?null:money(n(v.grossDelta()).add(n(originEr)).add(n(v.sdlDelta()))),List.of()));count++;}
  var capture=sources.capture(a.tenantId(),company,m,List.of());access.enter(a,store,company,capture.stores());var opts=new LinkedHashMap<UUID,EmployeeOption>();capture.lines().forEach(l->opts.put(l.employee().id(),new EmployeeOption(l.employee().id(),l.employee().name()+" · "+l.employee().employeeNo(),l.profile()==null?null:l.profile().rule().basis(),l.profile()==null?null:PayrollGeneration.mode(l.profile().rule()))));records.forEach(r->{var l=r.calculation()==null?null:r.calculation().cumulative().lines().getFirst();opts.putIfAbsent(r.employeeId(),new EmployeeOption(r.employeeId(),r.employeeName(),l==null?null:l.profile().rule().basis(),l==null?null:PayrollGeneration.mode(l.profile().rule())));});
  return new Page(company,m.toString(),List.copyOf(opts.values()),records,totals.isEmpty()?null:formalTotals(a.tenantId(),company,m,normal,totals),people.size(),count);
 }
 private PayBreakdown.Values formalTotals(UUID t,UUID company,YearMonth m,PayrollRepository.State normal,List<PayBreakdown.Values> totals){var v=PayBreakdown.sum(totals);var sdl=new SegmentCompanySdl(jdbc,json).recognisedSegments(t,company,m);if(normal!=null&&SegmentRepository.formal(normal.status())&&normal.calculation()!=null)sdl=sdl.add(n(normal.calculation().totalSdl()));return new PayBreakdown.Values(v.basic(),v.overtime(),v.additional(),v.allowance(),v.accommodation(),v.reimbursements(),v.otherDeductions(),v.cdac(),v.employeeCpf(),v.employerCpf(),money(sdl),v.employerCharges(),v.gross(),v.net(),v.employerCpf()==null?null:money(n(v.gross()).add(n(v.reimbursements())).add(n(v.employerCpf())).add(sdl).add(n(v.employerCharges()))),v.items());}

 private Detail view(CurrentActor a,UUID store,SegmentRepository.State s){var person=employees.find(a.tenantId(),s.employee()).orElseThrow(WorkforceException::missing);var payments=repo.payments(a.tenantId(),s.id());var paid=payments.stream().map(p->n(p.amount()).multiply(java.math.BigDecimal.valueOf(p.reversesId()==null?1:-1))).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add);var c=s.calculation();boolean changed=false;if(c!=null&&SegmentRepository.formal(s.status())){var current=sources.captureSegment(s.tenant(),s.company(),s.employee(),s.month(),s.cutoff());access.enter(a,store,s.company(),current.stores());changed=SegmentSourceChanges.changed(s,current.lines().stream().findFirst().orElse(null));}if(c!=null&&!SegmentRepository.formal(s.status())&&!s.status().equals("voided")){try{changed=!c.fingerprint().equals(calculation.calculate(s).fingerprint());}catch(WorkforceException ex){changed=true;}}
  return new Detail(s.id(),s.company(),s.employee(),c==null?person.name():c.cumulative().lines().getFirst().employeeName(),c==null?payroll.company(s.tenant(),s.company()).name():c.cumulative().companyName(),s.month().toString(),s.from(),s.cutoff(),s.status(),s.version(),s.request(),c,payments,money(paid),c==null||c.delta().net()==null?null:money(n(c.delta().net()).subtract(paid)),changed);
 }
 public List<Slip> mine(CurrentActor a,UUID store,int year){gate.enter(a,store);if(year<2000||year>2100)throw WorkforceException.invalid();var self=employees.byAccount(a.tenantId(),a.actorId()).orElseThrow(WorkforceException::forbidden);return repo.mine(a.tenantId(),self.id(),year).stream().map(this::slip).toList();}
 public Slip mine(CurrentActor a,UUID store,UUID id){gate.enter(a,store);var self=employees.byAccount(a.tenantId(),a.actorId()).orElseThrow(WorkforceException::forbidden);var s=repo.find(a.tenantId(),id).filter(b->b.employee().equals(self.id())&&b.status().equals("published")).orElseThrow(WorkforceException::missing);return slip(s);}
 private Slip slip(SegmentRepository.State s){var c=s.calculation();var all=repo.payments(s.tenant(),s.id());var paid=all.stream().map(p->n(p.amount()).multiply(BigDecimal.valueOf(p.reversesId()==null?1:-1))).reduce(BigDecimal.ZERO,BigDecimal::add);var d=c.delta();var clean=new PayBreakdown.Values(d.basic(),d.overtime(),d.additional(),d.allowance(),d.accommodation(),d.reimbursements(),d.otherDeductions(),d.cdac(),d.employeeCpf(),d.employerCpf(),d.sdl(),d.employerCharges(),d.gross(),d.net(),d.employerCost(),d.items().stream().map(i->new Component(i.label(),i.kind(),i.amount())).toList());var currentLine=c.cumulative().lines().getFirst();var previousLine=c.previousId()==null?null:repo.find(s.tenant(),c.previousId()).orElseThrow(WorkforceException::missing).calculation().cumulative().lines().getFirst();String payable=currentLine.input().payableDays()==null?null:n(currentLine.input().payableDays()).subtract(previousLine==null||previousLine.input().payableDays()==null?BigDecimal.ZERO:n(previousLine.input().payableDays())).stripTrailingZeros().toPlainString();return new Slip(s.id(),c.cumulative().companyName(),c.cumulative().lines().getFirst().employeeName(),s.month().toString(),s.from(),s.cutoff(),s.status(),clean,d.net(),money(paid),money(n(d.net()).subtract(paid)),all.stream().map(p->new PublicPayment(p.id(),p.amount(),p.paymentDate(),p.method(),p.reference(),p.reversesId(),p.bank())).toList(),currentLine.profile().rule().basis(),currentLine.profile().rule().rate(),currentLine.workSeconds()-(previousLine==null?0:previousLine.workSeconds()),currentLine.overtimeSeconds()-(previousLine==null?0:previousLine.overtimeSeconds()),currentLine.input().workingDays(),payable);}
 @Transactional public Detail payment(CurrentActor a,UUID store,UUID id,UUID payment,PaymentWrite w){
  var initial=state(a,store,id);lock(a,initial);gate.sourceWrite(a);var s=state(a,store,id);noSelf(a,s);if(!s.status().equals("published")||payment==null||w==null||!s.employee().equals(w.employeeId())||w.paymentDate()==null||w.paymentDate().isAfter(today())||w.paymentDate().isBefore(s.month().atDay(1))||!PaymentPreferences.method(w.method())||w.amount()==null||!w.amount().matches("[0-9]{1,8}(\\.[0-9]{1,2})?")||n(w.amount()).signum()<=0||w.note()==null||w.note().isBlank()||w.note().length()>500)throw WorkforceException.invalid();String bank=PaymentPreferences.bank(w.bank()),reference=w.reference()==null?"":w.reference();if(reference.length()>100||w.method().equals("bank")&&(bank.isBlank()||reference.isBlank())||w.method().equals("cash")&&!bank.isEmpty())throw WorkforceException.invalid();
  var list=repo.payments(a.tenantId(),id);var old=repo.payment(a.tenantId(),payment).orElse(null);if(old!=null){if(list.stream().noneMatch(p->p.id().equals(payment))||!old.employeeId().equals(w.employeeId())||!old.amount().equals(money(n(w.amount())))||!old.paymentDate().equals(w.paymentDate())||!old.method().equals(w.method())||!old.reference().equals(reference)||!old.note().equals(w.note())||!Objects.equals(old.reversesId(),w.reversesId())||!old.actorId().equals(a.actorId())||!old.bank().equals(bank))throw WorkforceException.conflict();return view(a,store,s);}
  if(w.reversesId()!=null){var original=list.stream().filter(p->p.id().equals(w.reversesId())).findFirst().orElseThrow(WorkforceException::missing);if(original.reversesId()!=null||list.stream().anyMatch(p->original.id().equals(p.reversesId()))||n(original.amount()).compareTo(n(w.amount()))!=0||!original.method().equals(w.method())||!original.bank().equals(bank)||w.paymentDate().isBefore(original.paymentDate()))throw WorkforceException.conflict();}else if(n(view(a,store,s).remaining()).compareTo(n(w.amount()))<0)throw new WorkforceException("WORKFORCE_PAYROLL_OVERPAYMENT",409);
  repo.payment(s,new Payment(payment,s.employee(),money(n(w.amount())),w.paymentDate(),w.method(),reference,w.note(),w.reversesId(),a.actorId(),clock.instant(),bank));audit.changed(a,store,w.reversesId()==null?"segment.payment":"segment.payment-reverse",payment,null,Map.of("segmentId",id,"employeeId",s.employee()));return view(a,store,s);
 }
}
